; Wizard sound driver - Doraemon DX 10 (J) [S]
; bank 4 $4000-$7D31 and bank 0 $2846-$3045
; Generated by tools/wiz_gen.py. Assembles byte-identical with RGBDS 1.0.0.

INCLUDE "wizard_sound.inc"

; ---- WRAM ----
DEF wSndPause        EQU $C6C6   ;   1 byte: non-zero: music structs neither tick nor write registers
DEF wSndPan          EQU $C6C7   ;   8 bytes: NR51 bits per struct (cmds $8A-$8C)
DEF wSndMasterVol    EQU $C6CF   ;   1 byte: NR50 copy (fade)
DEF wSndFadeOn       EQU $C6D0   ;   1 byte: 1 = fade running
DEF wSndFadeRate     EQU $C6D1   ;   1 byte: frames per fade step
DEF wSndFadeCount    EQU $C6D2   ;   1 byte: fade frame counter
DEF wSndUnused0D     EQU $C6D3   ;   2 bytes: not used
DEF wSndChIdx        EQU $C6D5   ;   1 byte: struct being processed (0-7)
DEF wSndLastMask     EQU $C6D6   ;   1 byte: channel mask of the last sound started
DEF wSndNote         EQU $C6D7   ;   1 byte: note byte being read
DEF wSndRawFlag      EQU $C6D8   ;   1 byte: compared with $7D, never written by the driver
DEF wSndActive       EQU $C6D9   ;   1 byte: bit n = struct n running (0-3 music ch1-4, 4-7 SFX ch1-4)
DEF wSndTracks       EQU $C6DA   ; 272 bytes: 8 structs of $22 bytes

SECTION "Wizard sound driver", ROMX[$4000], BANK[4]

; Pause music: structs 0-3 stop ticking and writing registers (SFX keep running). Not called by either game.
Sound_Pause::
    push af                                         ; 4000
    ld a,$01                                        ; 4001
    ld [wSndPause],a                                ; 4003
    pop af                                          ; 4006
    ret                                             ; 4007

; Undo Sound_Pause. Not called by either game.
Sound_Resume::
    push af                                         ; 4008
    sub a                                           ; 4009
    ld [wSndPause],a                                ; 400A
    pop af                                          ; 400D
    ret                                             ; 400E

; Boot: sound on, NR51=0, NR50=$77, ch3 DAC on, all structs stopped, pan bytes reset.
Sound_Init::
    ld a,$80                                        ; 400F
    ldh [rNR52],a                                   ; 4011  NR52: sound on
    ld a,$00                                        ; 4013
    ldh [rNR51],a                                   ; 4015  NR51: all channels off
    ld a,$77                                        ; 4017
    ld [wSndMasterVol],a                            ; 4019
    ldh [rNR50],a                                   ; 401C  NR50: full volume
    ldh a,[rNR30]                                   ; 401E
    or $80                                          ; 4020
    ldh [rNR30],a                                   ; 4022  NR30: ch3 DAC on
    sub a                                           ; 4024
    ld [wSndActive],a                               ; 4025  no struct running
    sub a                                           ; 4028
    ld [wSndTracks + 0 * TRK_SIZE + TRK_FLAGS],a    ; 4029  clear TRK_FLAGS of all 8 structs
    ld [wSndTracks + 1 * TRK_SIZE + TRK_FLAGS],a    ; 402C
    ld [wSndTracks + 2 * TRK_SIZE + TRK_FLAGS],a    ; 402F
    ld [wSndTracks + 3 * TRK_SIZE + TRK_FLAGS],a    ; 4032
    ld [wSndTracks + 4 * TRK_SIZE + TRK_FLAGS],a    ; 4035
    ld [wSndTracks + 5 * TRK_SIZE + TRK_FLAGS],a    ; 4038
    ld [wSndTracks + 6 * TRK_SIZE + TRK_FLAGS],a    ; 403B
    ld [wSndTracks + 7 * TRK_SIZE + TRK_FLAGS],a    ; 403E
    ld a,$11                                        ; 4041  pan bytes: $11,$22,$44,$88 for structs 0-3 and 4-7
    ld b,$04                                        ; 4043
    ld hl,wSndPan                                   ; 4045
    ld de,wSndPan + 4                               ; 4048
.l404B:
    ld [hli],a                                      ; 404B
    ld [de],a                                       ; 404C
    inc de                                          ; 404D
    sla a                                           ; 404E
    dec b                                           ; 4050
    jr nz,.l404B                                    ; 4051
    ret                                             ; 4053

; a = frames per step. Each step lowers both NR50 volumes by 1 (stops at 0). Ends only through Sound_StopAll.
Sound_FadeOut::
    ld [wSndFadeRate],a                             ; 4054  frames per step
    ld a,$01                                        ; 4057
    ld [wSndFadeOn],a                               ; 4059  fade on
    dec a                                           ; 405C
    ld [wSndFadeCount],a                            ; 405D  counter = 0
    ret                                             ; 4060

; a = value, b = struct mask: TRK_VOLOFS of each struct whose bit is set = a. Not called by either game.
Sound_SetVolOffset::
    ld c,$08                                        ; 4061  8 structs
    ld hl,wSndTracks + 0 * TRK_SIZE + TRK_VOLOFS    ; 4063
.l4066:
    push af                                         ; 4066
    bit 0,b                                         ; 4067
    jr z,.l406C                                     ; 4069
    ld [hl],a                                       ; 406B  TRK_VOLOFS = a
.l406C:
    pop af                                          ; 406C
    ld de,TRK_SIZE                                  ; 406D
    add hl,de                                       ; 4070
    srl b                                           ; 4071
    dec c                                           ; 4073
    jr nz,.l4066                                    ; 4074
    ret                                             ; 4076

; Stop every struct, silence the channels, cancel the fade, NR50=$77.
Sound_StopAll::
    sub a                                           ; 4077  keep nothing

; a = mask of structs to keep (StopAll enters with a=0). Not called directly by either game.
Sound_StopExcept::
    ld c,a                                          ; 4078
    ld a,[wSndActive]                               ; 4079
    and c                                           ; 407C
    ld [wSndActive],a                               ; 407D  wSndActive &= keep mask
    ld e,$EE                                        ; 4080  NR51 mask for ch1 (rotated each pass)
    ld d,$FE                                        ; 4082  NR52 mask for ch1 (writing it has no effect)
    ld b,$04                                        ; 4084
.l4086:
    ld a,c                                          ; 4086
    bit 0,a                                         ; 4087  music bit of this channel kept?
    jr z,.l408F                                     ; 4089
    bit 4,a                                         ; 408B  and its SFX bit kept? then leave the channel alone
    jr nz,.l4099                                    ; 408D
.l408F:
    ldh a,[rNR51]                                   ; 408F  take the channel out of NR51
    and e                                           ; 4091
    ldh [rNR51],a                                   ; 4092
    ldh a,[rNR52]                                   ; 4094
    and d                                           ; 4096
    ldh [rNR52],a                                   ; 4097
.l4099:
    rr c                                            ; 4099
    ld a,e                                          ; 409B
    rlca                                            ; 409C
    ld e,a                                          ; 409D
    ld a,d                                          ; 409E
    rlca                                            ; 409F
    ld d,a                                          ; 40A0
    dec b                                           ; 40A1
    jr nz,.l4086                                    ; 40A2
    sub a                                           ; 40A4
    ld [wSndFadeOn],a                               ; 40A5  fade off
    ld a,$77                                        ; 40A8
    ld [wSndMasterVol],a                            ; 40AA
    ldh [rNR50],a                                   ; 40AD  NR50 = $77
    ret                                             ; 40AF

; c = sound id. Starts the tracks listed in the header Snd_SoundTable[c].
Sound_Play::
    ld b,$00                                        ; 40B0
    ld hl,Snd_SoundTable                            ; 40B2  Snd_SoundTable[c] -> header
    add hl,bc                                       ; 40B5
    add hl,bc                                       ; 40B6
    ld a,[hli]                                      ; 40B7
    ld h,[hl]                                       ; 40B8
    ld l,a                                          ; 40B9
    ld a,[hl]                                       ; 40BA  header byte 0: struct mask
    ld [wSndLastMask],a                             ; 40BB
    bit 7,a                                         ; 40BE  SFX on ch4 (struct 7) in the mask? then keep NR51
    jr nz,.l40C7                                    ; 40C0
    push af                                         ; 40C2
    sub a                                           ; 40C3  else NR51 = 0
    ldh [rNR51],a                                   ; 40C4
    pop af                                          ; 40C6
.l40C7:
    ld b,$08                                        ; 40C7
    ld c,a                                          ; 40C9
    inc hl                                          ; 40CA
    ld de,wSndTracks + 0 * TRK_SIZE + TRK_PTR       ; 40CB  struct 0
.l40CE:
    bit 0,c                                         ; 40CE
    jr z,.l40DD                                     ; 40D0
    push hl                                         ; 40D2
    push de                                         ; 40D3
    push bc                                         ; 40D4
    call Snd_InitTrack                              ; 40D5  start this struct from the next header word
    pop bc                                          ; 40D8
    pop de                                          ; 40D9
    pop hl                                          ; 40DA
    inc hl                                          ; 40DB
    inc hl                                          ; 40DC
.l40DD:
    rr c                                            ; 40DD
    push bc                                         ; 40DF
    push hl                                         ; 40E0
    ld hl,TRK_SIZE                                  ; 40E1
    add hl,de                                       ; 40E4
    ld e,l                                          ; 40E5
    ld d,h                                          ; 40E6
    pop hl                                          ; 40E7
    pop bc                                          ; 40E8
    dec b                                           ; 40E9
    jr nz,.l40CE                                    ; 40EA
    ld a,[wSndLastMask]                             ; 40EC
    and $F0                                         ; 40EF  any SFX struct in the mask?
    jr z,.l40FF                                     ; 40F1
    ld a,[wSndLastMask]                             ; 40F3
    ld c,a                                          ; 40F6
    ld a,[wSndActive]                               ; 40F7
    or c                                            ; 40FA
    ld [wSndActive],a                               ; 40FB  SFX: add to the running structs
    ret                                             ; 40FE
.l40FF:
    ld a,[wSndLastMask]                             ; 40FF
    ld [wSndActive],a                               ; 4102  music: replaces everything, SFX included
    ret                                             ; 4105

; de = struct, hl -> track pointer in the header. Clears the struct and arms it for an immediate first row.
Snd_InitTrack:
    ld a,[hli]                                      ; 4106
    ld [de],a                                       ; 4107  TRK_PTR = track
    inc de                                          ; 4108
    ld a,[hl]                                       ; 4109
    ld [de],a                                       ; 410A
    ld l,e                                          ; 410B
    ld h,d                                          ; 410C
    inc hl                                          ; 410D
    ld a,$01                                        ; 410E  TRK_LENGTH = 1, TRK_GATE = 1
    ld c,$00                                        ; 4110
    ld [hli],a                                      ; 4112
    ld [hl],c                                       ; 4113
    inc hl                                          ; 4114
    ld [hli],a                                      ; 4115
    ld [hl],c                                       ; 4116
    inc hl                                          ; 4117
    sub a                                           ; 4118
    ld [hli],a                                      ; 4119  TRK_VOLUME, +7, +8, TRK_DUTY = 0
    ld [hli],a                                      ; 411A
    ld [hli],a                                      ; 411B
    ld [hli],a                                      ; 411C
    ld a,$06                                        ; 411D
    ld [hl],a                                       ; 411F  TRK_FLAGS = 6 (bits 1,2: never read)
    ld bc,$0005                                     ; 4120
    add hl,bc                                       ; 4123
    ld e,l                                          ; 4124
    ld d,h                                          ; 4125
    dec hl                                          ; 4126
    ld [hl],d                                       ; 4127
    dec hl                                          ; 4128
    ld [hl],e                                       ; 4129  TRK_SP = TRK_STACK
    ld de,$000E                                     ; 412A
    add hl,de                                       ; 412D
    sub a                                           ; 412E
    ld [hli],a                                      ; 412F  clear both envelopes (pos + pointer)
    ld [hli],a                                      ; 4130
    ld [hli],a                                      ; 4131
    ld [hli],a                                      ; 4132
    ld [hli],a                                      ; 4133
    ld [hli],a                                      ; 4134
    ret                                             ; 4135

; Call once per frame: fade, then tick every running struct, then write the registers.
Sound_Update::
    ld a,[wSndFadeOn]                               ; 4136  fade running?
    cp $01                                          ; 4139
    jr nz,.l416B                                    ; 413B
    ld a,[wSndFadeRate]                             ; 413D
    ld c,a                                          ; 4140
    ld a,[wSndFadeCount]                            ; 4141
    inc a                                           ; 4144
    ld [wSndFadeCount],a                            ; 4145
    cp c                                            ; 4148  step every wSndFadeRate frames
    jr c,.l416B                                     ; 4149
    sub a                                           ; 414B
    ld [wSndFadeCount],a                            ; 414C
    ld a,[wSndMasterVol]                            ; 414F
    ld e,a                                          ; 4152
    and $88                                         ; 4153  keep the VIN bits
    ld c,a                                          ; 4155
    ld a,e                                          ; 4156
    and $07                                         ; 4157
    jr z,.l415C                                     ; 4159
    dec a                                           ; 415B  right volume - 1 (min 0)
.l415C:
    ld d,a                                          ; 415C
    ld a,e                                          ; 415D
    and $70                                         ; 415E
    jr z,.l4164                                     ; 4160
    sub $10                                         ; 4162  left volume - 1 (min 0)
.l4164:
    or d                                            ; 4164
    or c                                            ; 4165
    ld [wSndMasterVol],a                            ; 4166
    ldh [rNR50],a                                   ; 4169
.l416B:
    sub a                                           ; 416B
    ld [wSndChIdx],a                                ; 416C  struct 0
    ld a,[wSndActive]                               ; 416F
    ld hl,wSndTracks + 0 * TRK_SIZE + TRK_PTR       ; 4172
    ld c,a                                          ; 4175
.l4176:
    bit 0,c                                         ; 4176  running?
    jr z,.l418F                                     ; 4178
    push hl                                         ; 417A
    push bc                                         ; 417B
    ld a,[wSndChIdx]                                ; 417C
    cp $04                                          ; 417F  music struct and paused: no tick
    jr nc,.l418A                                    ; 4181
    ld a,[wSndPause]                                ; 4183
    and $01                                         ; 4186
    jr nz,.l418D                                    ; 4188
.l418A:
    call Snd_TickTrack                              ; 418A  tick it
.l418D:
    pop bc                                          ; 418D
    pop hl                                          ; 418E
.l418F:
    ld de,TRK_SIZE                                  ; 418F
    add hl,de                                       ; 4192
    rr c                                            ; 4193
    ld a,[wSndChIdx]                                ; 4195
    inc a                                           ; 4198
    ld [wSndChIdx],a                                ; 4199
    cp $08                                          ; 419C
    jr c,.l4176                                     ; 419E
    call Snd_OutputAll                              ; 41A0  then write the registers
    ret                                             ; 41A3

; Output pass: Snd_OutputChannel for structs 0-7.
Snd_OutputAll:
    ld a,[wSndActive]                               ; 41A4
    ld b,a                                          ; 41A7
    ld c,$00                                        ; 41A8
    ld hl,wSndTracks + 0 * TRK_SIZE + TRK_PTR       ; 41AA
.l41AD:
    push bc                                         ; 41AD
    push hl                                         ; 41AE
    call Snd_OutputChannel                          ; 41AF
    pop hl                                          ; 41B2
    pop bc                                          ; 41B3
    ld de,TRK_SIZE                                  ; 41B4
    add hl,de                                       ; 41B7
    srl b                                           ; 41B8
    inc c                                           ; 41BA
    ld a,c                                          ; 41BB
    cp $08                                          ; 41BC
    jr c,.l41AD                                     ; 41BE
    ret                                             ; 41C0

; hl = struct, c = struct index, b = active mask shifted so bit 0 = this struct.
Snd_OutputChannel:
    ld a,c                                          ; 41C1
    cp $04                                          ; 41C2
    jr nc,.l41D0                                    ; 41C4  music struct:
    ld a,[wSndPause]                                ; 41C6
    and a                                           ; 41C9
    ret nz                                          ; 41CA    paused: nothing
    bit 4,b                                         ; 41CB    SFX running on this channel: nothing
    jr z,.l41D0                                     ; 41CD
    ret                                             ; 41CF
.l41D0:
    bit 0,b                                         ; 41D0  struct not running
    ret z                                           ; 41D2
    ld b,$00                                        ; 41D3
    ld a,c                                          ; 41D5
    push hl                                         ; 41D6
    ld hl,Snd_NRx2Table                             ; 41D7  c = NRx2 of the channel
    add hl,bc                                       ; 41DA
    ld c,[hl]                                       ; 41DB
    pop hl                                          ; 41DC
    ld b,a                                          ; 41DD
    ld de,$000A                                     ; 41DE
    add hl,de                                       ; 41E1
    bit 0,[hl]                                      ; 41E2  TRK_FLAGS bit 0: note sounding?
    jp z,Snd_OutputOff                              ; 41E4
    push hl                                         ; 41E7
    ld de,$0014                                     ; 41E8  pitch envelope:
    add hl,de                                       ; 41EB
.l41EC:
    ld a,[hli]                                      ; 41EC  e = position
    ld e,a                                          ; 41ED
    inc hl                                          ; 41EE
    ld a,[hld]                                      ; 41EF
    and a                                           ; 41F0  no pitch envelope
    jr z,.l4233                                     ; 41F1
    push hl                                         ; 41F3
    ld l,[hl]                                       ; 41F4
    ld h,a                                          ; 41F5
    ld d,$00                                        ; 41F6
    add hl,de                                       ; 41F8
    ld a,[hl]                                       ; 41F9
    cp $81                                          ; 41FA  $81: restart
    jr nz,.l4204                                    ; 41FC
    pop hl                                          ; 41FE
    dec hl                                          ; 41FF
    ld [hl],$00                                     ; 4200
    jr .l41EC                                       ; 4202
.l4204:
    cp $80                                          ; 4204  $80: hold (repeat previous value)
    jr nz,.l420D                                    ; 4206
    pop hl                                          ; 4208
    dec hl                                          ; 4209
    dec [hl]                                        ; 420A
    jr .l41EC                                       ; 420B
.l420D:
    pop hl                                          ; 420D
    dec hl                                          ; 420E
    ld de,$FFED                                     ; 420F  de = TRK_PERIOD
    add hl,de                                       ; 4212
    ld e,[hl]                                       ; 4213
    inc hl                                          ; 4214
    ld d,[hl]                                       ; 4215
    bit 7,a                                         ; 4216  add the signed step
    jr z,.l4221                                     ; 4218
    add a,e                                         ; 421A
    ld e,a                                          ; 421B
    ld a,$FF                                        ; 421C  BUG: d not updated, NRx4 below gets the old high byte
    adc a,d                                         ; 421E
    jr .l4227                                       ; 421F
.l4221:
    add a,e                                         ; 4221
    ld e,a                                          ; 4222
    ld a,$00                                        ; 4223
    adc a,d                                         ; 4225
    ld d,a                                          ; 4226
.l4227:
    ld [hld],a                                      ; 4227  TRK_PERIOD += step
    ld [hl],e                                       ; 4228
    inc c                                           ; 4229
    ld a,e                                          ; 422A
    ldh [c],a                                       ; 422B  NRx3 (overwritten below in the same frame)
    inc c                                           ; 422C
    ld a,d                                          ; 422D
    and $07                                         ; 422E
    ldh [c],a                                       ; 4230
    dec c                                           ; 4231
    dec c                                           ; 4232
.l4233:
    pop hl                                          ; 4233
    ld de,$0011                                     ; 4234  volume envelope:
    add hl,de                                       ; 4237
.l4238:
    push hl                                         ; 4238
    ld e,$00                                        ; 4239
    ld d,[hl]                                       ; 423B  d = position
    inc hl                                          ; 423C
    inc hl                                          ; 423D
    ld a,[hld]                                      ; 423E
    and a                                           ; 423F
    jp z,.l42DF                                     ; 4240  no volume envelope
    ld e,d                                          ; 4243
    ld d,a                                          ; 4244
    ld l,[hl]                                       ; 4245
    ld h,d                                          ; 4246
    ld d,$00                                        ; 4247
    add hl,de                                       ; 4249
    ld a,[hl]                                       ; 424A
    cp $80                                          ; 424B  $80: hold
    jr nz,.l4253                                    ; 424D
    pop hl                                          ; 424F
    dec [hl]                                        ; 4250
    jr .l4238                                       ; 4251
.l4253:
    cp $81                                          ; 4253  $81: restart
    jr nz,.l425C                                    ; 4255
    pop hl                                          ; 4257
    ld [hl],$00                                     ; 4258
    jr .l4238                                       ; 425A
.l425C:
    pop hl                                          ; 425C
    ld de,$FFEB                                     ; 425D
    add hl,de                                       ; 4260
    push hl                                         ; 4261
    ld e,a                                          ; 4262
    push de                                         ; 4263
    ld a,[hl]                                       ; 4264  TRK_VOLUME >> 4
    swap a                                          ; 4265
    and $0F                                         ; 4267
    ld de,$001B                                     ; 4269
    add hl,de                                       ; 426C
    add a,[hl]                                      ; 426D  + TRK_VOLOFS
    cp $10                                          ; 426E  clamp: >= $F0 -> 0, $10-$EF -> 15
    jr c,.l427B                                     ; 4270
    cp $F0                                          ; 4272
    jr c,.l4279                                     ; 4274
    sub a                                           ; 4276
    jr .l427B                                       ; 4277
.l4279:
    ld a,$0F                                        ; 4279
.l427B:
    add a,a                                         ; 427B  Snd_VolumeTable[vol][env value]
    add a,a                                         ; 427C
    add a,a                                         ; 427D
    ld e,a                                          ; 427E
    ld d,$00                                        ; 427F
    ld hl,Snd_VolumeTable                           ; 4281
    add hl,de                                       ; 4284
    add hl,de                                       ; 4285
    pop de                                          ; 4286
    ld d,$00                                        ; 4287
    add hl,de                                       ; 4289
    ld e,[hl]                                       ; 428A
    push de                                         ; 428B
    ld e,b                                          ; 428C
    ld d,$00                                        ; 428D
    ld hl,wSndPan                                   ; 428F  NR51 |= pan
    add hl,de                                       ; 4292
    ldh a,[rNR51]                                   ; 4293
    or [hl]                                         ; 4295
    ldh [rNR51],a                                   ; 4296
    pop de                                          ; 4298
    ld a,c                                          ; 4299
    cp $1C                                          ; 429A  ch3: NR32 from Snd_WaveVolTable
    jr nz,.l42AC                                    ; 429C
    ld a,e                                          ; 429E
    and $0F                                         ; 429F
    ld d,$00                                        ; 42A1
    push hl                                         ; 42A3
    ld hl,Snd_WaveVolTable                          ; 42A4
    add hl,de                                       ; 42A7
    ld a,[hl]                                       ; 42A8
    pop hl                                          ; 42A9
    jr .l42AF                                       ; 42AA
.l42AC:
    ld a,e                                          ; 42AC
    swap a                                          ; 42AD  others: NRx2 = level << 4 (no hardware envelope)
.l42AF:
    ldh [c],a                                       ; 42AF
    pop hl                                          ; 42B0
    ld de,$0003                                     ; 42B1
    add hl,de                                       ; 42B4
    dec c                                           ; 42B5
    ld a,c                                          ; 42B6
    cp $1A                                          ; 42B7  NRx1 = TRK_DUTY on ch1/ch2 only
    jr nc,.l42BD                                    ; 42B9
    ld a,[hl]                                       ; 42BB
    ldh [c],a                                       ; 42BC
.l42BD:
    inc hl                                          ; 42BD
    res 3,[hl]                                      ; 42BE  clear the release flag
    inc c                                           ; 42C0
    inc c                                           ; 42C1
    inc hl                                          ; 42C2
    ld a,[hli]                                      ; 42C3
    ldh [c],a                                       ; 42C4  NRx3 = period low
    inc c                                           ; 42C5
    ld a,c                                          ; 42C6
    cp $1E                                          ; 42C7  ch3/ch4:
    jr z,.l42CF                                     ; 42C9
    cp $23                                          ; 42CB
    jr nz,.l42D8                                    ; 42CD
.l42CF:
    call Snd_IsChannelOn                            ; 42CF    still running: no retrigger
    jr z,.l42D8                                     ; 42D2
    ld a,[hl]                                       ; 42D4
    ldh [c],a                                       ; 42D5
    jr .l42DC                                       ; 42D6
.l42D8:
    ld a,[hl]                                       ; 42D8  NRx4 = period high + trigger (every frame on ch1/ch2)
    or $80                                          ; 42D9
    ldh [c],a                                       ; 42DB
.l42DC:
    jp Snd_OutputOff.l4353                          ; 42DC
.l42DF:
    pop hl                                          ; 42DF
    ld de,$FFEF                                     ; 42E0
    add hl,de                                       ; 42E3
    res 0,[hl]                                      ; 42E4  no envelope: one-shot. Clear "sounding" so this is written only once
    res 3,[hl]                                      ; 42E6
    dec hl                                          ; 42E8
    ld a,c                                          ; 42E9
    cp $1A                                          ; 42EA  NRx1 = TRK_DUTY on ch1/ch2 only
    jr nc,.l42F2                                    ; 42EC
    ld a,[hl]                                       ; 42EE
    dec c                                           ; 42EF
    ldh [c],a                                       ; 42F0
    inc c                                           ; 42F1
.l42F2:
    push hl                                         ; 42F2
    ld e,b                                          ; 42F3
    ld d,$00                                        ; 42F4
    ld hl,wSndPan                                   ; 42F6  NR51 |= pan
    add hl,de                                       ; 42F9
    ldh a,[rNR51]                                   ; 42FA
    or [hl]                                         ; 42FC
    ldh [rNR51],a                                   ; 42FD
    pop hl                                          ; 42FF
    dec hl                                          ; 4300
    dec hl                                          ; 4301
    dec hl                                          ; 4302
    push hl                                         ; 4303
    ld a,[hl]                                       ; 4304  TRK_VOLUME >> 4
    swap a                                          ; 4305
    and $0F                                         ; 4307
    ld de,$001B                                     ; 4309
    add hl,de                                       ; 430C
    add a,[hl]                                      ; 430D  + TRK_VOLOFS, clamped
    cp $10                                          ; 430E
    jr c,.l431B                                     ; 4310
    cp $F0                                          ; 4312
    jr c,.l4319                                     ; 4314
    sub a                                           ; 4316
    jr .l431B                                       ; 4317
.l4319:
    ld a,$0F                                        ; 4319
.l431B:
    pop hl                                          ; 431B
    ld e,a                                          ; 431C
    ld a,c                                          ; 431D
    cp $1C                                          ; 431E  ch3: NR32 from Snd_WaveVolTable
    jr nz,.l432E                                    ; 4320
    ld d,$00                                        ; 4322
    push hl                                         ; 4324
    ld hl,Snd_WaveVolTable                          ; 4325
    add hl,de                                       ; 4328
    ld a,[hl]                                       ; 4329
    ldh [c],a                                       ; 432A
    pop hl                                          ; 432B
    jr .l4332                                       ; 432C
.l432E:
    ld a,e                                          ; 432E
    swap a                                          ; 432F  NRx2 = level << 4
    ldh [c],a                                       ; 4331
.l4332:
    inc c                                           ; 4332
    ld de,$0005                                     ; 4333
    add hl,de                                       ; 4336
    ld a,[hli]                                      ; 4337  NRx3
    ldh [c],a                                       ; 4338
    inc c                                           ; 4339
    ld a,[hl]                                       ; 433A
    or $80                                          ; 433B  NRx4 + trigger
    ldh [c],a                                       ; 433D
    jp Snd_OutputOff.l4353                          ; 433E

; Note not sounding: if a release is pending, take the channel out of NR51.
Snd_OutputOff:
    bit 3,[hl]                                      ; 4341  release pending?
    jr z,.l4353                                     ; 4343
    res 3,[hl]                                      ; 4345
    ld c,b                                          ; 4347
    ld b,$00                                        ; 4348
    ld hl,Snd_NR51ClearMask                         ; 434A  NR51 &= ~channel bits
    add hl,bc                                       ; 434D
    ldh a,[rNR51]                                   ; 434E
    and [hl]                                        ; 4350
    ldh [rNR51],a                                   ; 4351
.l4353:
    ret                                             ; 4353

; nz if NR52 says hardware channel b is still running.
Snd_IsChannelOn:
    ldh a,[rNR52]                                   ; 4354
    push hl                                         ; 4356
    push de                                         ; 4357
    ld e,b                                          ; 4358
    ld d,$00                                        ; 4359
    ld hl,Snd_NR52Mask                              ; 435B  NR52 bit of this channel
    add hl,de                                       ; 435E
    and [hl]                                        ; 435F
    pop de                                          ; 4360
    pop hl                                          ; 4361
    ret                                             ; 4362

; hl = struct. Gate countdown (release at 0, else advance both envelopes), then length countdown (read a row at 0).
Snd_TickTrack:
    ld bc,$0004                                     ; 4363  TRK_GATE
    add hl,bc                                       ; 4366
    ld c,[hl]                                       ; 4367
    inc hl                                          ; 4368
    ld b,[hl]                                       ; 4369
    dec hl                                          ; 436A
    ld a,c                                          ; 436B
    or b                                            ; 436C
    jr z,.l439C                                     ; 436D  gate already 0: skip
    dec bc                                          ; 436F
    ld [hl],c                                       ; 4370
    inc hl                                          ; 4371
    ld [hl],b                                       ; 4372
    dec hl                                          ; 4373
    ld a,b                                          ; 4374
    or c                                            ; 4375
    jr z,.l4387                                     ; 4376  gate ran out
    ld de,$0017                                     ; 4378
    add hl,de                                       ; 437B
    inc [hl]                                        ; 437C  TRK_VOLENVPOS + 1
    inc hl                                          ; 437D
    inc hl                                          ; 437E
    inc hl                                          ; 437F
    inc [hl]                                        ; 4380  TRK_PITCHPOS + 1
    ld de,$FFE6                                     ; 4381
    add hl,de                                       ; 4384
    jr .l439C                                       ; 4385
.l4387:
    push hl                                         ; 4387
    ld bc,$0006                                     ; 4388
    add hl,bc                                       ; 438B
    res 0,[hl]                                      ; 438C  release: not sounding, release pending
    set 3,[hl]                                      ; 438E
    ld de,$0011                                     ; 4390
    add hl,de                                       ; 4393
    ld [hl],$00                                     ; 4394  both envelopes back to position 0
    inc hl                                          ; 4396
    inc hl                                          ; 4397
    inc hl                                          ; 4398
    ld [hl],$00                                     ; 4399
    pop hl                                          ; 439B
.l439C:
    dec hl                                          ; 439C
    ld b,[hl]                                       ; 439D  TRK_LENGTH
    dec hl                                          ; 439E
    ld c,[hl]                                       ; 439F
    ld a,c                                          ; 43A0
    or b                                            ; 43A1
    jr z,.l43AD                                     ; 43A2  0: read now
    dec bc                                          ; 43A4
    ld [hl],c                                       ; 43A5
    inc hl                                          ; 43A6
    ld [hl],b                                       ; 43A7
    ld a,b                                          ; 43A8
    dec hl                                          ; 43A9
    or c                                            ; 43AA
    jr nz,.l43B2                                    ; 43AB  not yet 0
.l43AD:
    dec hl                                          ; 43AD
    dec hl                                          ; 43AE
    call Snd_ReadRow                                ; 43AF
.l43B2:
    ret                                             ; 43B2

; hl = struct. Execute commands until a note/tie/rest row.
Snd_ReadRow:
    ld c,[hl]                                       ; 43B3
    inc hl                                          ; 43B4
    ld b,[hl]                                       ; 43B5
    ld a,[bc]                                       ; 43B6  row byte
    cp $80                                          ; 43B7
    jr nc,Snd_DoCommand                             ; 43B9  command
    cp $7D                                          ; 43BB  $7D: the next byte is the note
    jr nz,.l43C1                                    ; 43BD
    inc bc                                          ; 43BF
    ld a,[bc]                                       ; 43C0
.l43C1:
    ld [wSndNote],a                                 ; 43C1  note
    inc bc                                          ; 43C4
    ld a,[bc]                                       ; 43C5  length
    inc bc                                          ; 43C6
    ld e,a                                          ; 43C7
    ld a,[bc]                                       ; 43C8  peek at the next row byte
    ld d,a                                          ; 43C9
    ld a,e                                          ; 43CA
    ld [hl],b                                       ; 43CB  TRK_PTR = that next byte
    dec hl                                          ; 43CC
    ld [hl],c                                       ; 43CD
    ld bc,$0002                                     ; 43CE
    add hl,bc                                       ; 43D1
    ld [hl],a                                       ; 43D2  TRK_LENGTH = length
    inc hl                                          ; 43D3
    inc hl                                          ; 43D4
    ld e,a                                          ; 43D5
    ld a,d                                          ; 43D6
    cp $7E                                          ; 43D7  next byte $7E (tie): gate = length + 1, so no release in between
    jr nz,.l43DC                                    ; 43D9
    inc e                                           ; 43DB
.l43DC:
    ld a,e                                          ; 43DC
    ld [hl],a                                       ; 43DD  TRK_GATE
    ld bc,$0007                                     ; 43DE
    add hl,bc                                       ; 43E1
    ld e,l                                          ; 43E2
    ld d,h                                          ; 43E3
    ld a,[wSndNote]                                 ; 43E4
    ld c,a                                          ; 43E7
    ld a,[wSndRawFlag]                              ; 43E8  never written by the driver (0): this branch is dead
    cp $7D                                          ; 43EB
    jr z,.l4404                                     ; 43ED
    ld a,c                                          ; 43EF
    cp $7E                                          ; 43F0  $7E tie: nothing else
    jr z,.l441D                                     ; 43F2
    cp $7F                                          ; 43F4  $7F rest
    jr z,.l441E                                     ; 43F6
    ld hl,Snd_FreqTable                             ; 43F8
    ld b,$00                                        ; 43FB
    ld a,[wSndChIdx]                                ; 43FD  struct 3 (music ch4): the byte is the NR43 value
    cp $03                                          ; 4400
    jr nz,.l440C                                    ; 4402
.l4404:
    ld a,c                                          ; 4404
    ld [de],a                                       ; 4405
    inc de                                          ; 4406
    sub a                                           ; 4407
    ld [de],a                                       ; 4408
    jp .l4414                                       ; 4409
.l440C:
    add hl,bc                                       ; 440C  TRK_PERIOD = Snd_FreqTable[note]
    add hl,bc                                       ; 440D
    ld a,[hl]                                       ; 440E
    ld [de],a                                       ; 440F
    inc hl                                          ; 4410
    inc de                                          ; 4411
    ld a,[hl]                                       ; 4412
    ld [de],a                                       ; 4413
.l4414:
    ld l,e                                          ; 4414
    ld h,d                                          ; 4415
    dec hl                                          ; 4416
    dec hl                                          ; 4417
    set 0,[hl]                                      ; 4418  TRK_FLAGS: sounding, bit 2 (never read)
    set 2,[hl]                                      ; 441A
    ret                                             ; 441C
.l441D:
    ret                                             ; 441D
.l441E:
    dec hl                                          ; 441E
    set 3,[hl]                                      ; 441F  rest: release pending, not sounding
    res 0,[hl]                                      ; 4421
    ret                                             ; 4423

; a = command byte $80-$93: jump through Snd_CmdTable with hl = struct, bc -> command.
Snd_DoCommand:
    ld e,l                                          ; 4424  de = struct
    ld d,h                                          ; 4425
    dec de                                          ; 4426
    push bc                                         ; 4427
    sub $80                                         ; 4428  Snd_CmdTable[a - $80]
    ld c,a                                          ; 442A
    ld b,$00                                        ; 442B
    ld hl,Snd_CmdTable                              ; 442D
    add hl,bc                                       ; 4430
    add hl,bc                                       ; 4431
    ld a,[hl]                                       ; 4432
    ld c,a                                          ; 4433
    inc hl                                          ; 4434
    ld a,[hl]                                       ; 4435
    ld h,a                                          ; 4436
    ld l,c                                          ; 4437
    pop bc                                          ; 4438
    jp hl                                           ; 4439

; Command handlers for $80-$93
Snd_CmdTable:
    dw Cmd_End                     ; $80 end
    dw Cmd_Volume                  ; $81 volume
    dw Cmd_LoopStart               ; $82 loop
    dw Cmd_LoopEnd                 ; $83 end loop
    dw Cmd_Wave                    ; $84 wave
    dw Cmd_Jump                    ; $85 jump
    dw Cmd_Call                    ; $86 call
    dw Cmd_Return                  ; $87 return
    dw Cmd_VolEnv                  ; $88 volume envelope
    dw Cmd_PitchEnv                ; $89 pitch envelope
    dw Cmd_PanLeft                 ; $8A pan left
    dw Cmd_PanRight                ; $8B pan right
    dw Cmd_PanCentre               ; $8C pan centre
    dw Cmd_Nop                     ; $8D
    dw Cmd_Nop                     ; $8E
    dw Cmd_Nop                     ; $8F
    dw Cmd_Duty                    ; $90 duty 0
    dw Cmd_Duty                    ; $91 duty 1
    dw Cmd_Duty                    ; $92 duty 2
    dw Cmd_Duty                    ; $93 duty 3

; $8C: pan[struct] = Snd_PanTable[struct] (both sides)
Cmd_PanCentre:
    ld l,e                                          ; 4462
    ld h,d                                          ; 4463
    inc bc                                          ; 4464
    ld [hl],c                                       ; 4465
    inc hl                                          ; 4466
    ld [hl],b                                       ; 4467
    ld a,[wSndChIdx]                                ; 4468
    ld c,a                                          ; 446B
    ld b,$00                                        ; 446C
    ld hl,Snd_PanTable                              ; 446E  pan[struct] = Snd_PanTable[struct]
    add hl,bc                                       ; 4471
    ld a,[hl]                                       ; 4472
    ld hl,wSndPan                                   ; 4473
    add hl,bc                                       ; 4476
    ld [hl],a                                       ; 4477
    ld l,e                                          ; 4478
    ld h,d                                          ; 4479
    jp Snd_ReadRow                                  ; 447A

; $8A: pan[struct] = Snd_PanTable[struct] & $F0 (left only)
Cmd_PanLeft:
    ld l,e                                          ; 447D
    ld h,d                                          ; 447E
    inc bc                                          ; 447F
    ld [hl],c                                       ; 4480
    inc hl                                          ; 4481
    ld [hl],b                                       ; 4482
    ld a,[wSndChIdx]                                ; 4483
    ld c,a                                          ; 4486
    ld b,$00                                        ; 4487
    ld hl,Snd_PanTable                              ; 4489
    add hl,bc                                       ; 448C
    ld a,[hl]                                       ; 448D
    and $F0                                         ; 448E
    ld hl,wSndPan                                   ; 4490
    add hl,bc                                       ; 4493
    ld [hl],a                                       ; 4494
    ld l,e                                          ; 4495
    ld h,d                                          ; 4496
    jp Snd_ReadRow                                  ; 4497

; $8B: pan[struct] = Snd_PanTable[struct] & $0F (right only)
Cmd_PanRight:
    ld l,e                                          ; 449A
    ld h,d                                          ; 449B
    inc bc                                          ; 449C
    ld [hl],c                                       ; 449D
    inc hl                                          ; 449E
    ld [hl],b                                       ; 449F
    ld a,[wSndChIdx]                                ; 44A0
    ld c,a                                          ; 44A3
    ld b,$00                                        ; 44A4
    ld hl,Snd_PanTable                              ; 44A6
    add hl,bc                                       ; 44A9
    ld a,[hl]                                       ; 44AA
    and $0F                                         ; 44AB
    ld hl,wSndPan                                   ; 44AD
    add hl,bc                                       ; 44B0
    ld [hl],a                                       ; 44B1
    ld l,e                                          ; 44B2
    ld h,d                                          ; 44B3
    jp Snd_ReadRow                                  ; 44B4

; NR51 bits per struct (both sides)
Snd_PanTable:
    db $11, $22, $44, $88, $11, $22, $44, $88

; $8D-$8F: no effect
Cmd_Nop:
    ld l,e                                          ; 44BF
    ld h,d                                          ; 44C0
    inc bc                                          ; 44C1
    ld [hl],c                                       ; 44C2
    inc hl                                          ; 44C3
    ld [hl],b                                       ; 44C4
    dec hl                                          ; 44C5
    jp Snd_ReadRow                                  ; 44C6

; $90-$93: TRK_DUTY = (cmd & 3) << 6
Cmd_Duty:
    ld l,e                                          ; 44C9
    ld h,d                                          ; 44CA
    ld a,[bc]                                       ; 44CB  a = the command byte itself
    inc bc                                          ; 44CC
    ld [hl],c                                       ; 44CD
    inc hl                                          ; 44CE
    ld [hl],b                                       ; 44CF
    ld bc,$0008                                     ; 44D0
    add hl,bc                                       ; 44D3
    swap a                                          ; 44D4  (cmd & 3) << 6
    sla a                                           ; 44D6
    sla a                                           ; 44D8
    and $C0                                         ; 44DA
    ld [hl],a                                       ; 44DC
    ld bc,$FFF7                                     ; 44DD
    add hl,bc                                       ; 44E0
    jp Snd_ReadRow                                  ; 44E1

; $89 n: pitch envelope n (PitchEnvTable), from its start
Cmd_PitchEnv:
    ld l,e                                          ; 44E4
    ld h,d                                          ; 44E5
    push hl                                         ; 44E6
    inc bc                                          ; 44E7
    ld a,[bc]                                       ; 44E8
    inc bc                                          ; 44E9
    ld [hl],c                                       ; 44EA
    inc hl                                          ; 44EB
    ld [hl],b                                       ; 44EC
    ld bc,$001D                                     ; 44ED
    add hl,bc                                       ; 44F0
    ld e,l                                          ; 44F1
    ld d,h                                          ; 44F2
    ld c,a                                          ; 44F3
    ld b,$00                                        ; 44F4
    ld hl,PitchEnvTable                             ; 44F6  PitchEnvTable[n]
    add hl,bc                                       ; 44F9
    add hl,bc                                       ; 44FA
    sub a                                           ; 44FB  TRK_PITCHPOS = 0, TRK_PITCHENV = pointer
    ld [de],a                                       ; 44FC
    inc de                                          ; 44FD
    ld a,[hli]                                      ; 44FE
    ld [de],a                                       ; 44FF
    inc de                                          ; 4500
    ld a,[hl]                                       ; 4501
    ld [de],a                                       ; 4502
    pop hl                                          ; 4503
    jp Snd_ReadRow                                  ; 4504

; $88 n: volume envelope n (VolEnvTable), from its start
Cmd_VolEnv:
    ld l,e                                          ; 4507
    ld h,d                                          ; 4508
    push hl                                         ; 4509
    inc bc                                          ; 450A
    ld a,[bc]                                       ; 450B
    inc bc                                          ; 450C
    ld [hl],c                                       ; 450D
    inc hl                                          ; 450E
    ld [hl],b                                       ; 450F
    ld bc,$001A                                     ; 4510
    add hl,bc                                       ; 4513
    ld e,l                                          ; 4514
    ld d,h                                          ; 4515
    ld c,a                                          ; 4516
    ld b,$00                                        ; 4517
    ld hl,VolEnvTable                               ; 4519  VolEnvTable[n]
    add hl,bc                                       ; 451C
    add hl,bc                                       ; 451D
    ld a,$00                                        ; 451E  TRK_VOLENVPOS = 0, TRK_VOLENV = pointer
    ld [de],a                                       ; 4520
    inc de                                          ; 4521
    ld a,[hli]                                      ; 4522
    ld [de],a                                       ; 4523
    inc de                                          ; 4524
    ld a,[hl]                                       ; 4525
    ld [de],a                                       ; 4526
    pop hl                                          ; 4527
    jp Snd_ReadRow                                  ; 4528

; $87: continue at TRK_RETURN
Cmd_Return:
    ld l,e                                          ; 452B
    ld h,d                                          ; 452C
    ld bc,$0018                                     ; 452D
    add hl,bc                                       ; 4530
    ld e,[hl]                                       ; 4531  TRK_PTR = TRK_RETURN
    inc hl                                          ; 4532
    ld d,[hl]                                       ; 4533
    ld bc,$FFE8                                     ; 4534
    add hl,bc                                       ; 4537
    ld [hl],d                                       ; 4538
    dec hl                                          ; 4539
    ld [hl],e                                       ; 453A
    jp Snd_ReadRow                                  ; 453B

; $86 ptr: TRK_RETURN = next row, jump to ptr (one level)
Cmd_Call:
    ld l,e                                          ; 453E
    ld h,d                                          ; 453F
    inc bc                                          ; 4540
    ld a,[bc]                                       ; 4541
    ld e,a                                          ; 4542
    inc bc                                          ; 4543
    ld a,[bc]                                       ; 4544
    ld d,a                                          ; 4545
    inc bc                                          ; 4546
    ld [hl],e                                       ; 4547  TRK_PTR = target
    inc hl                                          ; 4548
    ld [hl],d                                       ; 4549
    dec hl                                          ; 454A
    push hl                                         ; 454B
    ld de,$0018                                     ; 454C
    add hl,de                                       ; 454F
    ld [hl],c                                       ; 4550  TRK_RETURN = after the argument
    inc hl                                          ; 4551
    ld [hl],b                                       ; 4552
    pop hl                                          ; 4553
    jp Snd_ReadRow                                  ; 4554

; $85 ptr: jump
Cmd_Jump:
    ld l,e                                          ; 4557
    ld h,d                                          ; 4558
    inc bc                                          ; 4559
    ld a,[bc]                                       ; 455A
    ld [hl],a                                       ; 455B
    inc hl                                          ; 455C
    inc bc                                          ; 455D
    ld a,[bc]                                       ; 455E
    ld [hl],a                                       ; 455F
    dec hl                                          ; 4560
    jp Snd_ReadRow                                  ; 4561

; $84 n: copy wave n (WaveTable) into wave RAM
Cmd_Wave:
    ld l,e                                          ; 4564
    ld h,d                                          ; 4565
    inc bc                                          ; 4566
    ld a,[bc]                                       ; 4567
    inc bc                                          ; 4568
    ld [hl],c                                       ; 4569
    inc hl                                          ; 456A
    ld [hl],b                                       ; 456B
    dec hl                                          ; 456C
    push hl                                         ; 456D
    ld hl,WaveTable                                 ; 456E  WaveTable[n]
    ld c,a                                          ; 4571
    ld b,$00                                        ; 4572
    add hl,bc                                       ; 4574
    add hl,bc                                       ; 4575
    ld a,[hli]                                      ; 4576
    ld h,[hl]                                       ; 4577
    ld l,a                                          ; 4578
    ldh a,[rNR52]                                   ; 4579
    and $04                                         ; 457B  ch3 running?
    jr z,.l4589                                     ; 457D
    ldh a,[rNR51]                                   ; 457F
    and $BB                                         ; 4581  take it out of NR51
    ldh [rNR51],a                                   ; 4583
    ld a,$00                                        ; 4585
    ldh [rNR32],a                                   ; 4587  NR32 = 0 (mute) while loading
.l4589:
    ld de,_AUD3WAVERAM                              ; 4589  copy 16 bytes
.l458C:
    ld a,[hli]                                      ; 458C
    ld [de],a                                       ; 458D
    inc de                                          ; 458E
    ld a,e                                          ; 458F
    cp $40                                          ; 4590
    jr c,.l458C                                     ; 4592
    ldh a,[rNR32]                                   ; 4594
    and $9F                                         ; 4596  NR32: 100% (other bits kept)
    or $20                                          ; 4598
    ldh [rNR32],a                                   ; 459A
    pop hl                                          ; 459C
    jp Snd_ReadRow                                  ; 459D

; $82 n: push (n, next row) on the loop stack
Cmd_LoopStart:
    ld l,e                                          ; 45A0
    ld h,d                                          ; 45A1
    inc bc                                          ; 45A2
    ld a,[bc]                                       ; 45A3
    inc bc                                          ; 45A4
    ld [hl],c                                       ; 45A5
    inc hl                                          ; 45A6
    ld [hl],b                                       ; 45A7
    dec hl                                          ; 45A8
    push hl                                         ; 45A9
    ld de,$000D                                     ; 45AA  push count, return pointer at TRK_SP
    add hl,de                                       ; 45AD
    ld e,[hl]                                       ; 45AE
    inc hl                                          ; 45AF
    ld d,[hl]                                       ; 45B0
    ld [de],a                                       ; 45B1
    inc de                                          ; 45B2
    ld a,c                                          ; 45B3
    ld [de],a                                       ; 45B4
    inc de                                          ; 45B5
    ld a,b                                          ; 45B6
    ld [de],a                                       ; 45B7
    inc de                                          ; 45B8
    ld [hl],d                                       ; 45B9
    dec hl                                          ; 45BA
    ld [hl],e                                       ; 45BB
    pop hl                                          ; 45BC
    jp Snd_ReadRow                                  ; 45BD

; $83: count-1; jump back while non-zero, else pop
Cmd_LoopEnd:
    ld l,e                                          ; 45C0
    ld h,d                                          ; 45C1
    inc bc                                          ; 45C2
    ld [hl],c                                       ; 45C3
    inc hl                                          ; 45C4
    ld [hl],b                                       ; 45C5
    dec hl                                          ; 45C6
    push hl                                         ; 45C7
    ld de,$000D                                     ; 45C8
    add hl,de                                       ; 45CB
    ld e,[hl]                                       ; 45CC
    inc hl                                          ; 45CD
    ld d,[hl]                                       ; 45CE
    dec de                                          ; 45CF  TRK_SP - 3: the top entry
    dec de                                          ; 45D0
    dec de                                          ; 45D1
    ld a,[de]                                       ; 45D2
    dec a                                           ; 45D3  count - 1
    ld [de],a                                       ; 45D4
    and a                                           ; 45D5
    jr z,.l45E6                                     ; 45D6
    inc de                                          ; 45D8
    ld a,[de]                                       ; 45D9  not 0: TRK_PTR = loop start (entry stays)
    ld c,a                                          ; 45DA
    inc de                                          ; 45DB
    ld a,[de]                                       ; 45DC
    ld b,a                                          ; 45DD
    pop hl                                          ; 45DE
    ld [hl],c                                       ; 45DF
    inc hl                                          ; 45E0
    ld [hl],b                                       ; 45E1
    dec hl                                          ; 45E2
    jp Snd_ReadRow                                  ; 45E3
.l45E6:
    ld [hl],d                                       ; 45E6  0: pop
    dec hl                                          ; 45E7
    ld [hl],e                                       ; 45E8
    pop hl                                          ; 45E9
    jp Snd_ReadRow                                  ; 45EA

; $81 v: TRK_VOLUME high nibble = v
Cmd_Volume:
    ld l,e                                          ; 45ED
    ld h,d                                          ; 45EE
    inc bc                                          ; 45EF
    ld a,[bc]                                       ; 45F0
    inc bc                                          ; 45F1
    ld [hl],c                                       ; 45F2
    inc hl                                          ; 45F3
    ld [hl],b                                       ; 45F4
    dec hl                                          ; 45F5
    push hl                                         ; 45F6
    ld bc,$0006                                     ; 45F7
    add hl,bc                                       ; 45FA
    swap a                                          ; 45FB  high nibble = v, low nibble kept
    ld c,a                                          ; 45FD
    ld a,[hl]                                       ; 45FE
    and $0F                                         ; 45FF
    or c                                            ; 4601
    ld [hl],a                                       ; 4602
    pop hl                                          ; 4603
    jp Snd_ReadRow                                  ; 4604

; $80: stop this struct
Cmd_End:
    ld l,e                                          ; 4607
    ld h,d                                          ; 4608
    ld bc,$000A                                     ; 4609
    add hl,bc                                       ; 460C
    res 0,[hl]                                      ; 460D  not sounding, no release pending
    res 3,[hl]                                      ; 460F
    ld a,[wSndChIdx]                                ; 4611
    ld c,a                                          ; 4614
    ld b,$00                                        ; 4615
    ld hl,Snd_NR51ClearMask                         ; 4617  NR51 &= ~channel bits
    add hl,bc                                       ; 461A
    ldh a,[rNR51]                                   ; 461B
    and [hl]                                        ; 461D
    ldh [rNR51],a                                   ; 461E
    ld hl,Snd_ActiveClearMask                       ; 4620  clear its bit in wSndActive (no more rows read)
    add hl,bc                                       ; 4623
    ld a,[wSndActive]                               ; 4624
    and [hl]                                        ; 4627
    ld [wSndActive],a                               ; 4628
    ret                                             ; 462B

; wSndActive mask that clears the bit of struct n
Snd_ActiveClearMask:
    db $FE, $FD, $FB, $F7, $EF, $DF, $BF, $7F

